package dev.algorithmlearning.api.reviews.data; import dev.algorithmlearning.api.reviews.application.*; import java.util.*; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; @Repository public class JpaReviewRepository implements ReviewRepository {private final NamedParameterJdbcTemplate jdbc;public JpaReviewRepository(NamedParameterJdbcTemplate j){jdbc=j;}public Review save(Review r){jdbc.update("insert into reviews (id,problem_id,confidence,reviewed_at,next_review_at,notes,policy_version) values (:id,:problemId,:confidence,:reviewedAt,:nextReviewAt,:notes,:policyVersion)",new BeanPropertySqlParameterSource(r));return r;}public List<Review> due(UUID u,java.time.Instant now,int l,int o){return query("select r.* from reviews r join problems p on p.id=r.problem_id where p.user_id=:u and r.next_review_at<=:now order by r.next_review_at asc,r.problem_id asc limit :l offset :o",u,null,now,l,o);}public List<Review> history(UUID u,UUID p,int l,int o){return query("select r.* from reviews r join problems p on p.id=r.problem_id where p.user_id=:u and r.problem_id=:p order by r.reviewed_at desc,r.id desc limit :l offset :o",u,p,null,l,o);}private List<Review> query(String sql,UUID u,UUID p,java.time.Instant now,int l,int o){var x=new MapSqlParameterSource().addValue("u",u).addValue("p",p).addValue("now",now).addValue("l",l).addValue("o",o);return jdbc.query(sql,x,(rs,n)->new Review((UUID)rs.getObject("id"),(UUID)rs.getObject("problem_id"),rs.getInt("confidence"),rs.getTimestamp("reviewed_at").toInstant(),rs.getTimestamp("next_review_at").toInstant(),rs.getString("notes"),rs.getString("policy_version")));}}
